package com.mhmmad.setramahjong;
import android.app.Activity;import android.os.*;import android.content.*;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.net.Uri;import android.view.*;import android.widget.*;import android.media.AudioManager;import android.media.ToneGenerator;import java.util.*;
public final class MainActivity extends Activity {
 private static final int JADE=0xff245f50,DARK=0xff102e2a,CREAM=0xffffefd1,GOLD=0xffe4bb72;
 private static final String[] SIG={"","◆","✦","●","▲","■","◇","✚","○","△","□","✧","◎","✿","✽","≋","☘","◈","✶"};
 private final Handler handler=new Handler(Looper.getMainLooper()); private LinearLayout root;private GridLayout grid;private TextView status;private android.content.SharedPreferences prefs;
 private Puzzle game;private String lang="en";private int selected=-1,second=-1,hintA=-1,hintB=-1,level=0,epoch=0;private boolean locked=false,finished=false,daily=false;private long started;private ToneGenerator tone;
 private String tr(String en,String ar,String pt){return lang.equals("ar")?ar:lang.equals("pt")?pt:en;}
 private int dp(int x){return (int)(x*getResources().getDisplayMetrics().density+.5f);}
 @Override public void onCreate(Bundle b){super.onCreate(b);if(Build.VERSION.SDK_INT>=33){getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::navigateBack);}prefs=getSharedPreferences("setra_v2",MODE_PRIVATE);lang=prefs.getString("language","en");try{tone=new ToneGenerator(AudioManager.STREAM_MUSIC,25);}catch(RuntimeException ignored){}home();}
 @Override protected void onDestroy(){handler.removeCallbacksAndMessages(null);if(tone!=null)tone.release();super.onDestroy();}
 private void sound(boolean success){if(tone!=null&&prefs.getBoolean("sound",true))tone.startTone(success?ToneGenerator.TONE_PROP_ACK:ToneGenerator.TONE_PROP_NACK,90);}
 private GradientDrawable bg(int a,int b,int radius){GradientDrawable g=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{a,b});g.setCornerRadius(dp(radius));return g;}
 private TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setGravity(Gravity.CENTER);t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}
 private void add(View v){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(12);root.addView(v,p);}
 private Button btn(String s,Runnable r){Button b=new Button(this);b.setAllCaps(false);b.setText(s);b.setTextSize(17);b.setTextColor(CREAM);b.setBackground(bg(JADE,0xff193f36,16));b.setMinHeight(dp(54));b.setPadding(dp(10),dp(10),dp(10),dp(10));b.setElevation(dp(3));b.setOnClickListener(v->r.run());return b;}
 private void frame(String title,String subtitle){onHome=false;ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(18),dp(42),dp(18),dp(30));root.setLayoutDirection(lang.equals("ar")?View.LAYOUT_DIRECTION_RTL:View.LAYOUT_DIRECTION_LTR);root.setBackground(bg(DARK,0xff214a3b,0));scroll.addView(root);setContentView(scroll);add(text("✦   S E T R A   ✦",15,GOLD));add(text(title,32,CREAM));add(text(subtitle,15,GOLD));}
 private String name(int m){return m==0?tr("Classic Mahjong","ماجونغ الكلاسيكية","Mahjong clássico"):m==1?tr("Garden Routes","مسارات الحديقة","Caminhos do jardim"):tr("Memory Grove","بستان الذاكرة","Bosque da memória");}
 private void reset(){epoch++;handler.removeCallbacksAndMessages(null);game=null;locked=false;finished=false;selected=second=hintA=hintB=-1;}
 private void home(){reset();level=0;frame(tr("Tile sanctuary","حديقة البلاطات","Santuário das peças"),tr("Three ways to play • Offline","ثلاث طرق للعب • دون إنترنت","Três modos • Offline"));
  add(btn("✦  "+tr("Tile Quest • 24 levels","رحلة البلاطات • 24 مرحلة","Jornada • 24 fases"),this::campaign));
  for(int m=0;m<3;m++){final int mode=m;add(btn(name(m),()->choose(mode)));}
  add(btn("◈  "+tr("Daily puzzle","لغز اليوم","Enigma diário"),()->{long d=System.currentTimeMillis()/86400000L;level=0;start((int)(d%3),4,6,d,true);}));
  add(btn(tr("Progress & achievements","التقدم والإنجازات","Progresso e conquistas"),this::stats));add(btn(tr("Settings & help","الإعدادات والمساعدة","Configurações e ajuda"),this::settings));onHome=true;
 }
 private void choose(int m){reset();level=0;frame(name(m),tr("Choose board size","اختر حجم اللوحة","Escolha o tabuleiro"));for(int c:new int[]{4,6})for(int r:new int[]{4,6}){if(m==2&&r*c>36)continue;add(btn(r+" × "+c,()->start(m,r,c,System.nanoTime(),false)));}add(btn(tr("Back","رجوع","Voltar"),this::home));}
 private void campaign(){reset();frame(tr("Tile Quest","رحلة البلاطات","Jornada das peças"),tr("Complete a level to unlock the next","أكمل مرحلة لفتح التالية","Conclua uma fase para liberar a próxima"));int unlocked=prefs.getInt("unlocked",1);for(int n=1;n<=24;n++){final int k=n;Button b=btn((n<unlocked?"★ ":n>unlocked?"🔒 ":"◆ ")+tr("Level ","مرحلة ","Fase ")+n+" • "+name((n-1)%3),()->{level=k;start((k-1)%3,k<10?4:6,k<5?4:6,202600L+k,false);});b.setEnabled(n<=unlocked);add(b);}add(btn(tr("Back","رجوع","Voltar"),this::home));}
 private void start(int m,int r,int c,long seed,boolean d){reset();game=new Puzzle(m,r,c,seed);daily=d;started=System.currentTimeMillis();show();}
 private void show(){frame(name(game.mode),game.mode==0?tr("Match uncovered tiles with a free side","طابق البلاطات المكشوفة ذات جانب حر","Combine peças livres e descobertas"):game.mode==1?tr("Connect equal tiles with at most two turns","اربط بلاطتين متطابقتين بانعطافين على الأكثر","Ligue peças iguais com até duas curvas"):tr("Reveal and remember matching pairs","اكشف الأزواج وتذكرها","Revele e memorize os pares"));
  status=text("",16,GOLD);add(status);grid=new GridLayout(this);grid.setColumnCount(game.cols);grid.setLayoutDirection(View.LAYOUT_DIRECTION_LTR);add(grid);draw();
  if(game.mode!=2)add(btn(tr("Hint","تلميح","Dica"),()->{int[] h=game.hint();hintA=h[0];hintB=h[1];draw();if(h[0]<0)status.setText(tr("No legal moves • restart","لا حركات قانونية • أعد المحاولة","Sem jogadas • reinicie"));}));
  add(btn(tr("Restart","إعادة","Reiniciar"),()->start(game.mode,game.rows,game.cols,game.seed,daily)));add(btn(tr("Home","الرئيسية","Início"),this::home));
 }
 private void draw(){grid.removeAllViews();status.setText(tr("Moves: ","الحركات: ","Jogadas: ")+game.moves+"  •  "+tr("Pairs left: ","الأزواج المتبقية: ","Pares restantes: ")+game.remaining()/2);
  for(int cell=0;cell<game.rows*game.cols;cell++){int i=game.visible(cell);int val=game.tiles[i];boolean exposed=game.mode!=2||i==selected||i==second;boolean highlight=i==selected||i==second||i==hintA||i==hintB;
   Button b=new Button(this);b.setAllCaps(false);b.setMinimumWidth(0);b.setMinWidth(0);b.setMinHeight(0);b.setPadding(0,0,0,0);b.setTextSize(24);b.setText(val==0?"":exposed?SIG[val]:"✦");b.setTextColor(highlight?DARK:exposed?JADE:GOLD);b.setBackground(bg(val==0?DARK:highlight?GOLD:exposed?CREAM:JADE,val==0?DARK:highlight?0xffd39a43:exposed?0xffd8bb83:0xff1b453a,9));b.setElevation(dp(val==0?0:i>=game.rows*game.cols?9:3));b.setAlpha(val==0?0.3f:game.free(i)?1f:0.6f);b.setEnabled(val!=0&&game.free(i));b.setContentDescription(val==0?tr("Empty","فارغ","Vazio"):exposed?tr("Tile ","بلاطة ","Peça ")+val:tr("Hidden tile","بلاطة مخفية","Peça oculta"));
   GridLayout.LayoutParams p=new GridLayout.LayoutParams(GridLayout.spec(cell/game.cols),GridLayout.spec(cell%game.cols,1,1f));p.width=0;p.height=dp(58);p.setMargins(dp(3),dp(3),dp(3),dp(3));grid.addView(b,p);b.setOnClickListener(v->tap(i));}
 }
 private void tap(int i){if(game==null||locked||finished||!game.free(i))return;hintA=hintB=-1;if(selected<0){selected=i;draw();return;}if(i==selected){selected=-1;draw();return;}int a=selected;second=i;game.moves++;if(game.remove(a,i)){sound(true);selected=second=-1;draw();if(game.remaining()==0)win();else if(game.mode!=2&&game.hint()[0]<0)status.setText(tr("No legal moves • restart","لا حركات قانونية • أعد المحاولة","Sem jogadas • reinicie"));}else{sound(false);if(game.mode==2){locked=true;draw();int e=epoch;handler.postDelayed(()->{if(e==epoch&&game!=null){locked=false;selected=second=-1;draw();}},700);}else{selected=i;second=-1;draw();}}}
 private void win(){finished=true;int count=prefs.getInt("wins",0)+1;android.content.SharedPreferences.Editor ed=prefs.edit().putInt("wins",count).putInt("wins"+game.mode,prefs.getInt("wins"+game.mode,0)+1);if(level>0)ed.putInt("unlocked",Math.max(prefs.getInt("unlocked",1),Math.min(25,level+1)));if(daily)ed.putLong("lastDaily",game.seed);ed.apply();int secs=(int)((System.currentTimeMillis()-started)/1000);new android.app.AlertDialog.Builder(this).setTitle("★ "+tr("Puzzle complete!","اكتمل اللغز!","Enigma concluído!")).setMessage(game.moves+" "+tr("moves","حركة","jogadas")+" • "+secs+" s").setPositiveButton(tr("Continue","متابعة","Continuar"),(d,w)->{if(level>0)campaign();else home();}).setCancelable(false).show();}
 private void stats(){reset();frame(tr("Your progress","تقدمك","Seu progresso"),tr("Local achievements","إنجازات محلية","Conquistas locais"));int n=prefs.getInt("wins",0);add(text("★  "+n+"  "+tr("completed puzzles","ألغاز مكتملة","enigmas concluídos"),24,CREAM));for(int m=0;m<3;m++)add(text(name(m)+" • "+prefs.getInt("wins"+m,0),20,GOLD));add(text(tr("First steps","الخطوات الأولى","Primeiros passos")+" "+(n>0?"★":"☆"),20,CREAM));add(text(tr("Puzzle master: 25 wins","خبير الألغاز: 25 فوزًا","Mestre: 25 vitórias")+" "+(n>=25?"★":"☆"),20,CREAM));add(btn(tr("Back","رجوع","Voltar"),this::home));}
 private void settings(){reset();frame(tr("Settings","الإعدادات","Configurações"),tr("Language • Sound • Rules","اللغة • الصوت • القواعد","Idioma • Som • Regras"));for(String l:new String[]{"en","ar","pt"})add(btn(l.equals("ar")?"العربية":l.equals("pt")?"Português (Brasil)":"English (UK)",()->{lang=l;prefs.edit().putString("language",l).apply();settings();}));add(btn(tr("Sound effects: ","المؤثرات الصوتية: ","Efeitos sonoros: ")+(prefs.getBoolean("sound",true)?tr("On","تشغيل","Ligado"):tr("Off","إيقاف","Desligado")),()->{prefs.edit().putBoolean("sound",!prefs.getBoolean("sound",true)).apply();settings();}));add(text(tr("Classic: free side and no tile above. Routes: two turns maximum. Memory: reveal pairs.","الكلاسيكية: جانب حر ولا بلاطة فوقها. المسارات: انعطافان كحد أقصى. الذاكرة: اكشف الأزواج.","Clássico: lado livre e sem peça acima. Caminhos: até duas curvas. Memória: revele pares."),16,CREAM));add(btn(tr("Privacy policy","سياسة الخصوصية","Política de privacidade"),()->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://github.com/mhmmad444410aa-ai/SetraMahjong/blob/main/PRIVACY_POLICY.md")));}catch(Exception ignored){}}));add(btn(tr("Back","رجوع","Voltar"),this::home));}
 private boolean onHome;
 private void navigateBack(){if(onHome)finish();else home();}
 @android.annotation.SuppressLint("GestureBackNavigation") // API 33+ uses the platform dispatcher; this override serves older Android.
 @Override public void onBackPressed(){navigateBack();}
}
